package services

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
)

// SummaryCache is a small LRU of LLM-generated section summaries, persisted to
// data/summaries.json so repeated detail-panel opens do not pay the
// generation cost again. The key covers (article, section) only, so summaries
// generated by summary-warm stay hittable from the Cloud Run deployment, where
// the live full text may differ in formatting. Stale summaries keep serving
// until the cache file is regenerated.
type SummaryCache struct {
	mu      sync.Mutex
	flushMu sync.Mutex
	path    string
	max     int
	order   []string          // keys in recency order, most recent last
	byKey   map[string]string // key -> summary text
}

func summaryCacheMax() int {
	if v := strings.TrimSpace(os.Getenv("SUMMARY_CACHE_MAX")); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			return n
		}
	}
	return 5000
}

var summaryCache = newSummaryCache("data/summaries.json", summaryCacheMax())

func newSummaryCache(path string, max int) *SummaryCache {
	c := &SummaryCache{path: path, max: max, byKey: map[string]string{}}
	c.load()
	return c
}

// summaryCacheKey is stable for a given (article, section) pair, independent
// of the article revision.
func summaryCacheKey(title, sectionLabel string) string {
	h := sha256.Sum256([]byte(title + "|" + sectionLabel))
	return hex.EncodeToString(h[:])
}

// headingMapCacheKey is stable for a given (article, heading-snapshot) pair.
// The LLM heading-resolution result is cheap to compute once per article
// revision, so we cache it keyed on the sorted snapshot of headings rather
// than the full text. Any revision that adds, removes, or renames a heading
// changes the snapshot and the stale map simply stops being found.
func headingMapCacheKey(title string, headings []string) string {
	sorted := make([]string, len(headings))
	copy(sorted, headings)
	sort.Strings(sorted)
	combined := strings.Join(sorted, "\n")
	h := sha256.Sum256([]byte("headingmap|" + title + "|" + combined))
	return hex.EncodeToString(h[:])
}

func (c *SummaryCache) Get(key string) (string, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	v, ok := c.byKey[key]
	if !ok {
		return "", false
	}
	c.touchLocked(key)
	return v, true
}

func (c *SummaryCache) Put(key, summary string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if _, ok := c.byKey[key]; !ok {
		c.order = append(c.order, key)
	}
	c.byKey[key] = summary
	c.touchLocked(key)
	for len(c.order) > c.max {
		oldest := c.order[0]
		c.order = c.order[1:]
		delete(c.byKey, oldest)
	}
}

// touchLocked moves key to the most-recent position. Caller holds the mutex.
func (c *SummaryCache) touchLocked(key string) {
	for i, k := range c.order {
		if k == key {
			copy(c.order[i:], c.order[i+1:])
			c.order = c.order[:len(c.order)-1]
			break
		}
	}
	c.order = append(c.order, key)
}

func (c *SummaryCache) load() {
	data, err := os.ReadFile(c.path)
	if err != nil {
		return
	}
	var raw map[string]string
	if err := json.Unmarshal(data, &raw); err != nil {
		return
	}
	keys := make([]string, 0, len(raw))
	for k := range raw {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		c.byKey[k] = raw[k]
		c.order = append(c.order, k)
	}
	if len(c.order) > c.max {
		c.order = c.order[len(c.order)-c.max:]
		fit := map[string]string{}
		for _, k := range c.order {
			fit[k] = c.byKey[k]
		}
		c.byKey = fit
	}
}

// flush atomically rewrites the backing file. Small enough to run after every
// Put; at most one JSON write per panel open.
func (c *SummaryCache) flush() {
	// Serialise whole flushes so a stale snapshot never renames over a newer
	// one and concurrent writers never share the tmp file.
	c.flushMu.Lock()
	defer c.flushMu.Unlock()
	c.mu.Lock()
	data, err := json.Marshal(c.byKey)
	c.mu.Unlock()
	if err != nil {
		return
	}
	if err := os.MkdirAll(filepath.Dir(c.path), 0o755); err != nil {
		return
	}
	tmp := c.path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return
	}
	_ = os.Rename(tmp, c.path)
}

// SummaryDisabled reports whether the LLM/summary pipeline must be bypassed
// (e.g. a Cloud Run deployment with no local Ollama). When true, sections are
// rendered from their raw blocks only.
func SummaryDisabled() bool {
	switch strings.ToLower(strings.TrimSpace(os.Getenv("TOKUSAN_SUMMARY_DISABLE"))) {
	case "1", "true", "yes", "on":
		return true
	}
	return false
}

func lookupSummary(key string) (string, bool) {
	return summaryCache.Get(key)
}

func saveSummary(key, summary string) {
	summaryCache.Put(key, summary)
	summaryCache.flush()
}
